return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T07:20:41+00:00','po-revision-date'=>'2026-09-26T07:20:41+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Ang pundasyon na paglabas ng muling ginawang Page Builder Sandwich: isang screen ng mga setting at Tungkol sa, isang front-end na output layer na walang footprint, at isang sample na content block.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Mga tagapagbigay ng AI','The makers of ChatGPT. A good all-rounder.'=>'Ang mga tagalikha ng ChatGPT. Isang magandang all-rounder.','The makers of Claude. Strong at writing and careful reasoning.'=>'Ang mga gumawa ng Claude. Magaling sa pagsulat at maingat sa pangangatwiran.','Google\'s Gemini models. Fast and inexpensive.'=>'Ang mga modelo ng Gemini ng Google. Mabilis at mura.','A European AI company with fast, inexpensive models.'=>'Isang kumpanya ng AI sa Europa na may mabilis at murang mga modelo.','Low-cost models that are good at writing and code.'=>'Mga murang modelo na magaling sa pagsusulat at code.','One key for models from many different providers.'=>'Isang susi para sa mga modelo mula sa iba\'t ibang provider.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Anumang serbisyo na gumagana tulad ng API ng OpenAI, kabilang ang isang modelong tumatakbo sa iyong sariling computer o server.','General (used when nothing more specific is set)'=>'Pangkalahatan (ginagamit kapag walang nakatakdang mas tiyak)','Writing and rewriting'=>'Pagsulat at muling pagsulat','Translation'=>'Pagsasalin','Code and CSS'=>'Code at CSS','Sorry, you are not allowed to access this page.'=>'Paumanhin, hindi ka pinapayagang ma-access ang pahinang ito.','These settings are shared by every plugin that uses them: %s.'=>'Ang mga setting na ito ay ibinabahagi ng bawat plugin na gumagamit sa mga ito: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Naka-encrypt ang iyong mga key sa database ng site na ito at ipinapadala lamang sa pinili mong provider — hindi kailanman sa amin.','Step 1 of 2: choose an AI provider'=>'Hakbang 1 sa 2: pumili ng provider ng AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Nagdadala ka ng sarili mong key, kaya direktang nagbabayad ka sa provider para sa kung ano ang ginagamit mo. Hindi sigurado? Aluman sa mga ito ay maayos na gumagana; maaari kang magdagdag ng iba mamaya.','Next'=>'Susunod','Step 2 of 2: connect %s'=>'Hakbang 2 sa 2: ikonekta ang %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Ilagay ang address ng iyong serbisyong tugma sa OpenAI, na nagtatapos sa /v1. Kinakailangan lamang ang isang susi kung humihingi nito ang serbisyo.','Open %s and sign in (or create a free account).'=>'Buksan ang %s at mag-sign in (o gumawa ng libreng account).','the %s API keys page'=>'ang %s pahina ng mga API key','Create a new key and copy it.'=>'Gumawa ng bagong key at kopyahin ito.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'I-paste ito sa ibaba at pindutin ang "Save and test". Nagpapadala kami ng isang maliit na kahilingan upang suriin kung gumagana ito.','Most providers need a little credit on the account before a key works: %s.'=>'Karamihan sa mga provider ay nangangailangan ng kaunting credit sa account bago gumana ang isang key: %s.','add credit'=>'magdagdag ng kredito','← Choose a different provider'=>'← Pumili ng ibang provider','Address'=>'Address','Saved key ends in …%s — paste a new one to replace it'=>'Ang naka-save na key ay nagtatapos sa …%s — magdikit ng bago para palitan ito','Key (optional)'=>'Susi (opsyonal)','API key'=>'API key','Save and test'=>'I-save at subukan','Providers'=>'Mga Provider','Provider'=>'Tagapagbigay','Status'=>'Katayuan','Key'=>'Susing Salita','Get a key'=>'Kumuha ng key','Test'=>'Subukan','Remove'=>'Alisin','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Nai-save sa mas bagong bersyon ng plugin: i-update ang plugin na ito, o ilagay ulit ang key.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Hindi na mabubuksan ang naka-save na key (nagbago ang mga security key ng site). Ilagay itong muli.','Not connected'=>'Hindi nakakonekta','Connected — last test passed %s'=>'Konekto — matagumpay ang huling pagsubok %s','Last test failed: %s'=>'Nabigo ang huling pagsubok: %s','Connected — not tested yet'=>'Konektado — hindi pa nasusubukan','Which model to use'=>'Aling modelo ang gagamitin','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ ang nagmamarka sa aming rekomendasyon para sa gawaing iyon. Kasama sa listahan ang bawat modelong magagamit ng iyong key, na direktang binabasa mula sa provider.','— Recommended for the provider —'=>'— Inirerekomenda para sa provider —','Save models'=>'I-save ang mga modelo','Refresh the model lists from the providers'=>'I-refresh ang mga listahan ng modelo mula sa mga provider','best quality'=>'pinakamataas na kalidad','lowest cost'=>'pinakamababang halaga','fastest'=>'pinakamabilis','Add a model yourself'=>'Magdagdag ng modelo nang mag-isa','A model came out today? Paste its exact name to use it straight away.'=>'May lumabas na modelo ngayon? I-paste ang eksaktong pangalan nito para magamit ito agad.','Model name'=>'Pangalan ng modelo','Add model'=>'Magdagdag ng modelo','Recommended models list'=>'Listahan ng mga inirerekomendang modelo','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Hindi na-verify ang listahan ng mga inirerekomendang modelo, kaya walang ipinapakitang rekomendasyon. I-reinstall ang plugin, o i-on ang mga pang-araw-araw na update sa ibaba.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Ang listahang ginagamit ay inilathala noong %s. Ang bawat pag-update ng plugin ay nagdadala ng bago.','Also check Zinn Digital® once a day for an updated list.'=>'Suriin din ang Zinn Digital® minsan sa isang araw para sa na-update na listahan.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Isang simpleng kahilingan sa pag-download lamang ang ipinapadala: walang key, walang address ng site, walang anuman tungkol sa iyong nilalaman. Ang listahan ay nilagdaan, at ang isang listahang nabigo sa pagsusuri ng lagda ay binabalewala.','Last checked %1$s: %2$s.'=>'Huling sinuri noong %1$s: %2$s.','Save, and check now if turned on'=>'I-save, at suriin ngayon kung naka-on','a newer list was installed'=>'isinalin ang isang mas bagong listahan','already up to date'=>'updated na ang lahat','the download failed the signature check and was ignored'=>'nabigo ang pag-download sa pagsusuri ng lagda at hindi pinansin','Zinn Digital® could not be reached; the current list stays in use'=>'Hindi maabot ang Zinn Digital®; nananatiling ginagamit ang kasalukuyang listahan','turned off'=>'naka-off','Open'=>'Buksan','Check their status page'=>'Suriin ang kanilang status page','Open your billing page'=>'Buksan ang iyong pahina ng pagsingil','Open your API keys page'=>'Buksan ang iyong pahina ng mga API key','Open the AI settings'=>'Buksan ang mga setting ng AI','Sorry, you are not allowed to do that.'=>'Paumanhin, hindi ka pinahihintulutang gawin iyon.','Unknown provider.'=>'Hindi kilalang provider.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Ilagay ang address ng iyong serbisyo, halimbawa ay http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Hindi iyon mukhang API key. Kopyahin itong muli nang walang mga espasyo.','Paste your API key first.'=>'I-paste muna ang iyong API key.','Key removed.'=>'Naalis na ang Susi.','Models saved.'=>'Na-save na ang mga modelo.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Ilagay ang eksaktong pangalan ng modelo, halimbawa ayon sa pagkakasulat sa dokumentasyon ng tagapagbigay.','Added %s. Choose it under "Which model to use".'=>'Idinagdag ang %s. Piliin ito sa ilalim ng "Aling modelo ang gagamitin".','Model removed.'=>'Inalis ang modelo.','Daily updates are off. The list that came with the plugin is used.'=>'Naka-off ang mga araw-araw na update. Ginagamit ang listahang kasama ng plugin.','Checked: %s.'=>'Nasuri: %s.','Model lists refreshed.'=>'Na-refresh na ang mga listahan ng modelo.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Nai-save ang iyong AI key ng mas bagong bersyon ng isa sa iyong mga plugin. I-update ang plugin na ito, o ilagay ulit ang key sa mga setting ng AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Hindi na mabubuksan ang iyong naka-save na AI key (nagbago ang mga security key ng site). Ilagay itong muli sa mga setting ng AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Hindi pa naka-set up ang AI. Magdagdag ng key para sa AI provider sa mga setting ng AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Walang napiling modelo para sa gawaing ito. Pumili ng isa sa mga setting ng AI.','That AI provider is not supported by this version of the plugin.'=>'Hindi sinusuportahan ang AI provider na iyon ng bersyong ito ng plugin.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Hindi maabot ng site na ito ang iyong serbisyo sa AI. Suriin kung ito ay tumatakbo at kung ang address nito ay naaabot mula sa iyong web server (ang isang serbisyo sa iyong sariling computer ay hindi maabot mula sa isang naka-host na site).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Hindi maabot ng site na ito ang %s. Suriin ang kanilang status page; kung gumagana sila, maaaring hinahararang ng iyong host ang mga papalabas na koneksyon, o mali ang address.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'Sabi ng %s na ang iyong account ay wala nang natitirang credit o quota. Magdagdag ng credit o pataasin ang iyong limit sa iyong account sa kanila, pagkatapos ay subukang muli.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'Hindi tinanggap ng %s ang iyong key. Maaaring mali ang pag-type nito, na-revoke o nag-expire na. Gumawa ng bagong key at i-paste ito dito.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'Tinanggihan ng %s ang kahilingang ito para sa iyong key. Maaaring walang access ang key sa model o feature na ito, o kailangang i-verify ang iyong account.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Ang modelong "%1$s" ay hindi available mula sa %2$s para sa iyong key. Pumili ng ibang modelo sa mga setting ng AI.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'Nililimitahan ng %s kung gaano kaaga maaaring magpadala ng mga kahilingan ang iyong key. Maghintay ng isang minuto at subukang muli, o itaas sa kanila ang iyong limitasyon sa rate.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'Nakakaranas ng mga problema ang %s ngayon (isang pagkaantala o labis na pagkarga sa kanilang bahagi). Walang mali sa iyong mga setting. Subukan muli makalipas ang ilang sandali.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Nabigo ang kahilingan sa AI dahil sa dahilan na hindi namin natukoy. Subukang muli; kung magpapatuloy ito, makipag-ugnayan sa suporta kasama ang mga detalye sa ibaba.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Tumugon ang AI provider sa anyong hindi mabasa ng plugin na ito. Subukan muli; kung magpapatuloy ito, pumili ng ibang modelo o makipag-ugnayan sa suporta.','Custom (OpenAI-compatible)'=>'Pasadya (tugma sa OpenAI)','Save a key for this provider first.'=>'Mag-save muna ng key para sa provider na ito.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Gumagana ang iyong key, ngunit walang nakalistang text model para rito ang provider. Magdagdag ng modelo sa ibaba.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Nakakonekta na. Sinagot ni %1$s gamit ang %2$s. Handa nang gamitin ang iyong mga feature ng AI.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Hindi pinahihintulutan ang iyong tungkulin bilang user na gumamit ng AI sa site na ito. Humingi ng tulong sa isang administrator.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon sa paggastos para sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Naabot na ng site na ito ang buwanang limitasyon nito para sa mga kahilingan sa AI. Maaari itong itaas ng isang administrator sa mga setting ng AI.','Usage and cost'=>'Paggamit at gastusin','The log, limits and role permissions apply to AI used through: %s.'=>'Nalalapat ang log, mga limitasyon, and mga pahintulot sa papel sa AI na ginagamit sa pamamagitan ng: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Ang mga gastos ay tinatayang lamang, na kinuha mula sa mga inilathalang presyo; ang isang modelo na walang kilalang presyo ay binibilang na zero.','This month: %1$s requests, about %2$s.'=>'Ngayong buwan: %1$s na mga kahilingan, humigit-kumulang %2$s.','When'=>'Kailan','Who'=>'Sino','Used for'=>'Gamitin para sa','Model'=>'Modelo','Tokens in / out'=>'Mga Token na papasok / palabas','About'=>'Tungkol sa','Result'=>'Resultado','No AI requests have been made yet.'=>'Wala pang ginagawang kahilingan sa AI.','Done'=>'Tapos na','Limits and permissions'=>'Mga limitasyon at pahintulot','Monthly spending limit (US dollars)'=>'Buwanang limitasyon sa paggastos (mga dolyar ng US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Iwanang bakasyon para walang limitasyon. Humihinto ang AI para sa natitirang buwan kapag naabot na ito ng tinatayang gastos.','Monthly request limit'=>'Limit sa buwanang kahilingan','Leave empty for no limit.'=>'Iwanang blangko para sa walang limitasyon.','Who may use AI'=>'Sino ang maaaring gumamit ng AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Mag-tack ng wala upang payagan ang lahat ng maaaring gumamit ng mga feature ng plugin na gumamit ng AI. Palaging magagamit ito ng mga Administrator.','Save limits and permissions'=>'I-save ang mga limitasyon at pahintulot','Limits and permissions saved.'=>'Na-save na ang mga limitasyon at pahintulot.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Nawawala ang mga script ng screen ng admin mula sa kopya ng plugin na ito. I-reinstall ito mula sa isang inilabas na package.','This screen needs JavaScript.'=>'Nangangailangan ang screen na ito ng JavaScript.','Languages'=>'Mga Wika','Upgrade'=>'Mag-upgrade','Pricing'=>'Pagpepresyo','Start Trial'=>'Simulan ang Pagsubok','Account'=>'Account','Contact Us'=>'Makipag-ugnayan sa Amin','Affiliation'=>'Pangalan ng Kaanib','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Kumusta %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Mag-opt in para makatanggap ng mga notification sa email para sa mga update sa seguridad at feature, nilalamang pang-edukasyon, at mga paminsan-minsang alok, at para magbahagi ng ilang pangunahing impormasyon tungkol sa kapaligiran ng WordPress. Makakatulong ito sa amin na gawing mas compatible ang %s sa iyong site at mas mahusay na magawa ang kailangan mo rito.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Mag-opt in para makatanggap ng mga notification sa email para sa mga update sa seguridad at feature, pang-edukasyon na nilalaman, at mga paminsan-minsang alok, at para magbahagi ng ilang pangunahing impormasyon tungkol sa kapaligiran ng WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Kung lalaktawan mo ito, ayos lang! Gagana pa rin nang maayos ang %1$s.','Allow & Continue'=>'Pahintulutan at Magpatuloy','verbSkip'=>'Laktawan','Skipping, please wait'=>'Laktawan, mangyaring maghintay','Continue'=>'Magpatuloy','Please wait'=>'Mangyaring maghintay','as activating pluginActivating'=>'Binabago','This will allow %s to'=>'Magbibigay-daan ito sa %s na','Privacy Policy'=>'Patakaran sa Pagkapribado','Terms of Service'=>'Mga Tuntunin ng Serbisyo','License Agreement'=>'Kasunduan sa Lisensya','Have a license key?'=>'Mayroon ka bang license key?','Activate License'=>'I-activate ang Lisensya','View Basic Profile Info'=>'Tingnan ang Pangunahing Impormasyon ng Profile','Your WordPress user\'s: first & last name, and email address'=>'Ang pangalan, apelyido, at email address ng iyong WordPress user','View Basic Website Info'=>'Tingnan ang Pangunahing Impormasyon ng Website','Homepage URL & title, WP & PHP versions, and site language'=>'Homepage URL at pamagat, mga bersyon ng WP at PHP, at wika ng site','View Basic %s Info'=>'Tingnan ang Pangunahing Impormasyon ng %s','Current %s & SDK versions, and if active or uninstalled'=>'Kasalukuyang %s & mga bersyon ng SDK, at kung aktivo o naka-uninstall','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Mga update, anunsyo, marketing, walang spam','View Diagnostic Info'=>'Tingnan ang Diagnostic Info','WordPress & PHP versions, site language & title'=>'WordPress at PHP na mga bersyon, wika at pamagat ng site','View Plugins & Themes List'=>'Tingnan ang Listahan ng mga Plugin at Tema','Names, slugs, versions, and if active or not'=>'Mga pangalan, slug, bersyon, at kung aktibo o hindi','optional'=>'opsyonal','Never miss an important update'=>'Huwag palampasin ang anumang mahalagang update','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Ipinakilala namin ang opt-in na ito upang hindi mo kailanman mapalampas ang isang mahalagang update at matulungan kaming gawing mas angkop ang %s sa iyong site at mas mahusay sa paggawa ng kung ano ang kailangan mo rito.','Thank you for updating to %1$s v%2$s!'=>'Salamat sa pag-update sa %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Ang prefix ay dapat may 1 hanggang 8 na maliit na titik o numero, magsimula sa isang titik, at hindi dapat ipangalan sa plugin.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Binuo ni Neil Lock, CEO ng Zinn Digital® Ltd','Version %s'=>'Bersyon %s','Page Builder Sandwich website'=>'Website ng Page Builder Sandwich','Zinn Digital® website'=>'website ng Zinn Digital®','Settings saved.'=>'Naka-save ang mga setting.','See the Pro plans and pricing'=>'Tingnan ang mga Pro plan at pagpepresyo','Front-end output'=>'Front-end output','Class name prefix'=>'Prefix ng pangalan ng klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Ang bawat pangalan ng klase na ipinrint ng plugin sa iyong mga pahina ay nagsisimula sa prefix na ito, kaya hindi inilalantad ng mga pahina kung aling plugin ang gumawa sa mga ito. 1 hanggang 8 na maliit na titik o numero, na nagsisimula sa isang titik.','Save'=>'I-save','Beta updates'=>'Mga beta na update','This site receives beta versions as updates.'=>'Ang site na ito ay tumatanggap ng mga beta na bersyon bilang mga update.','This site receives stable versions only.'=>'Tumatanggap lamang ang site na ito ng mga matatag na bersyon.','Change this on the Account page'=>'Baguhin ito sa pahina ng Account','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Inaalok ang mga beta bersyon sa mga lisensyadong Pro installation na konektado sa kanilang account. Kapag nakakonekta na, maaari kang sumali mula sa pahina ng Account.','Content'=>'Nilalaman','Heading'=>'Heading','Text'=>'Text','Style'=>'Estilo','Plain'=>'Karaniwan','Accent'=>'Aksento','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Walang mga wikang mapagpipilian. Lumilitaw ang switcher kapag naglista ang isang translation plugin ng dalawa o higit pang wika.','Switcher'=>'Switcher','Accessible label'=>'Madalasang label','Show the current language'=>'Ipakita ang kasalukuyang wika','block titleLanguage switcher (sample)'=>'Tagapagpalit ng Wika (sample)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Ilista ang mga wika ng site mula sa plugin ng pagsasalin, kapag aktibo ito. Hindi ito nag-render ng anuman kung hindi man.','block keywordlanguage'=>'wika','block keywordswitcher'=>'panlipat','block titleSample content'=>'Halimbawang nilalaman','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Isang heading at isang talata, na naka-render na may mga neutral na pangalan ng klase. Ito ang sangguniang bloke para sa kontrata sa pagsasalin.','block keywordsample'=>'sampol','block keywordtext'=>'teksto']];